// Original code-authored gameplay sprites. All colors come from the app palette.
window.TitleSprites=(()=>{const p=GamePalette.tokens;
 const items=[{id:'umbrella',name:'비 와도 때릴 수 있음',x:19,y:24,mx:17,my:14,size:144,angle:-19},{id:'fish',name:'신선한 한 방',x:81,y:25,mx:82,my:17,size:142,angle:18},{id:'pan',name:'오늘의 메뉴는 너',x:12,y:56,mx:10,my:48,size:145,angle:-27},{id:'clock',name:'네 턴은 없던 일로',x:88,y:57,mx:91,my:47,size:135,angle:17},{id:'ball',name:'일단 던져 봐',x:26,y:82,mx:17,my:82,size:105,angle:-12},{id:'sword',name:'그나마 무기 같은 것',x:75,y:82,mx:82,my:82,size:150,angle:24},{id:'pencil',name:'무기를 만드는 무기',x:44,y:10,mx:49,my:6,size:104,angle:65},{id:'shoe',name:'엄마의 전설 장비',x:56,y:90,mx:50,my:93,size:96,angle:-14}];
 function draw(canvas,id){canvas.width=canvas.height=32;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,32,32);
 const dot=(x,y,color)=>{c.fillStyle=p[color];c.fillRect(Math.round(x),Math.round(y),1,1);},rect=(x,y,w,h,color)=>{c.fillStyle=p[color];c.fillRect(x,y,w,h);};
 const line=(x,y,xx,yy,color='ink',width=1)=>{const steps=Math.max(Math.abs(xx-x),Math.abs(yy-y));for(let i=0;i<=steps;i++){const t=steps?i/steps:0;rect(Math.round(x+(xx-x)*t),Math.round(y+(yy-y)*t),width,width,color);}};
 const poly=(points,color)=>{for(let y=0;y<32;y++){const hits=[];for(let i=0;i<points.length;i++){const a=points[i],b=points[(i+1)%points.length];if((a[1]<=y&&b[1]>y)||(b[1]<=y&&a[1]>y))hits.push(a[0]+(y-a[1])*(b[0]-a[0])/(b[1]-a[1]));}hits.sort((a,b)=>a-b);for(let i=0;i+1<hits.length;i+=2)rect(Math.ceil(hits[i]),y,Math.floor(hits[i+1])-Math.ceil(hits[i])+1,1,color);}};
 const circle=(x,y,r,color)=>{for(let yy=-r;yy<=r;yy++)for(let xx=-r;xx<=r;xx++)if(xx*xx+yy*yy<=r*r)dot(x+xx,y+yy,color);};
 if(id==='umbrella'){line(16,5,16,27,'ink',2);line(12,27,16,27,'ink',2);line(11,24,11,27,'ink',2);poly([[3,16],[5,10],[10,6],[16,4],[22,6],[27,10],[30,16]],'ink');poly([[5,14],[8,9],[15,6],[15,14]],'water');poly([[17,6],[23,9],[28,14],[17,14]],'dragon');rect(6,15,8,2,'flying');rect(18,15,9,2,'water');line(11,8,8,13,'paper');}
 else if(id==='fish'){poly([[3,13],[8,8],[18,6],[25,10],[25,20],[18,24],[8,22],[3,17]],'ink');poly([[5,13],[9,10],[18,8],[24,12],[24,19],[17,22],[9,20],[5,17]],'water');poly([[24,13],[30,8],[29,17],[31,23],[24,19]],'ink');poly([[26,14],[28,12],[28,20],[26,18]],'flying');poly([[11,8],[16,3],[20,7]],'ink');rect(11,18,9,2,'flying');rect(6,12,4,5,'paper');dot(7,13,'ink');line(13,12,16,12,'dragon');line(16,15,20,15,'dragon');line(11,17,13,17,'dragon');}
 else if(id==='pan'){line(16,17,16,30,'ink',4);rect(17,21,2,8,'ground');circle(16,12,10,'ink');circle(16,12,8,'muted');circle(16,12,6,'dark');line(11,8,14,6,'metal',2);rect(18,17,3,1,'normal');circle(17,12,4,'paper');circle(18,12,2,'electric');dot(17,11,'surface');}
 else if(id==='clock'){circle(16,15,12,'ink');circle(16,15,10,'rock');circle(16,15,8,'paper');rect(14,1,5,3,'ink');rect(15,2,3,2,'electric');line(16,9,16,15,'ink');line(16,15,21,18,'ink');circle(16,15,1,'fighting');for(const [x,y]of [[15,7],[8,14],[23,14],[15,22]])rect(x,y,2,2,'ink');rect(8,26,3,3,'ink');rect(22,26,3,3,'ink');}
 else if(id==='ball'){circle(16,16,11,'ink');circle(16,16,9,'paper');poly([[8,20],[14,23],[23,17],[22,22],[17,25],[11,24]],'metal');for(let y=9;y<=22;y+=3){dot(11,y,'danger');dot(21,y,'danger');line(10,y,12,y+1,'fighting');line(20,y+1,22,y,'fighting');}rect(14,9,3,1,'surface');}
 else if(id==='sword'){poly([[16,2],[22,9],[20,20],[16,23],[11,20],[11,9]],'ink');poly([[16,5],[19,10],[18,19],[16,21],[13,19],[13,10]],'metal');poly([[16,5],[16,20],[13,17],[13,10]],'paper');rect(7,21,18,3,'ink');rect(9,21,14,1,'electric');rect(14,24,5,6,'ink');rect(15,24,3,4,'ground');rect(12,29,9,2,'ink');rect(14,29,5,1,'electric');}
 else if(id==='pencil'){poly([[11,4],[21,4],[21,24],[16,31],[11,24]],'ink');rect(13,6,6,16,'electric');rect(13,4,6,4,'illusion');rect(13,9,6,2,'metal');rect(13,12,2,10,'paper');poly([[13,23],[19,23],[16,28]],'rock');rect(16,28,1,2,'ink');}
 else if(id==='shoe'){poly([[11,3],[20,3],[24,8],[23,19],[20,27],[15,30],[8,28],[6,23],[8,16],[8,8]],'ink');poly([[12,5],[18,5],[22,9],[21,18],[18,25],[14,27],[9,25],[8,22],[10,15],[10,9]],'fighting');poly([[12,7],[18,7],[20,10],[18,16],[12,17],[10,13]],'paper');line(10,12,13,18,'ink',2);line(20,11,13,18,'ink',2);line(12,22,17,22,'electric',2);}
 else if(id==='water'){for(let i=0;i<5;i++){const x=5+i*5,y=6+(i%2)*7;poly([[x,y],[x+3,y+6],[x+3,y+10],[x,y+12],[x-2,y+9],[x-2,y+6]],'ink');poly([[x,y+3],[x+1,y+6],[x+1,y+9],[x-1,y+9]],'water');}line(5,28,27,28,'water');}
 else if(id==='guard'){poly([[16,3],[27,7],[26,20],[16,29],[6,20],[5,7]],'ink');poly([[16,6],[24,9],[23,19],[16,25],[9,19],[8,9]],'water');poly([[16,8],[16,22],[11,18],[10,10]],'flying');line(13,15,16,18,'paper',2);line(16,18,21,12,'paper',2);}
 else if(id==='electric'){poly([[17,2],[26,2],[19,13],[25,13],[9,30],[13,18],[6,18]],'ink');poly([[18,4],[22,4],[15,15],[21,15],[12,25],[16,16],[10,16]],'electric');}
 else if(id==='swirl'){for(let i=0;i<3;i++){const y=7+i*7;line(6+i*2,y,25-i*2,y,'ink',2);line(4+i*3,y+2,28-i*3,y+2,'water',3);}rect(10,5,8,1,'flying');rect(14,28,3,2,'water');}
 }
 return{items,draw};})();
